<?php

declare(strict_types=1);

namespace Windwalker\Edge\Test;

use PHPUnit\Framework\Attributes\Before;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use PHPUnit\Framework\TestCase;
use Windwalker\Edge\Compiler\EdgeCompiler;

/**
 * Asserts the PHP code generated by EdgeCompiler for each directive and echo syntax.
 *
 * Directives must be preceded by a non-word character, so templates use spaces between them.
 */
class EdgeCompilerTest extends TestCase
{
    protected EdgeCompiler $instance;

    #[Before]
    public function setUpCompiler(): void
    {
        $this->instance = new EdgeCompiler();
    }

    #[Test]
    #[DataProvider('compileProvider')]
    public function compileDirective(string $template, string $expected): void
    {
        self::assertSame($expected, $this->instance->compile($template));
    }

    public static function compileProvider(): array
    {
        $edgeArgs = "\$__edge->except(get_defined_vars(), ['__data', '__path'])";

        return [
            'if / elseif / else' => [
                '@if($a)x @elseif($b)y @else z @endif',
                '<?php if($a): ?>x <?php elseif($b): ?>y <?php else: ?> z <?php endif ?>',
            ],
            'unless' => [
                '@unless($a)x @endunless',
                '<?php if ( ! ($a)): ?>x <?php endif ?>',
            ],
            'switch' => [
                '@switch($a) @case(1)a @case(2)b @default c @endswitch',
                '<?php switch($a): case (1): ?>a <?php case (2): ?>b <?php default: ?> c <?php endswitch ?>',
            ],
            'for' => [
                '@for($i=0;$i<3;$i++)x @endfor',
                '<?php for($i=0;$i<3;$i++): ?>x <?php endfor ?>',
            ],
            'foreach' => [
                '@foreach($a as $b)x @endforeach',
                '<?php foreach($a as $b): ?>x <?php endforeach ?>',
            ],
            'forelse' => [
                '@forelse($a as $b)x @empty none @endforelse',
                '<?php $__empty_1 = true; foreach($a as $b): $__empty_1 = false; ?>x '
                . '<?php endforeach; if ($__empty_1): ?> none <?php endif ?>',
            ],
            'while' => [
                '@while($a)x @endwhile',
                '<?php while($a): ?>x <?php endwhile ?>',
            ],
            'break and continue' => [
                '@break @continue @break($b) @continue($b)',
                '<?php break; ?> <?php continue; ?> <?php if($b) break; ?> <?php if($b) continue; ?>',
            ],
            'php block' => [
                '@php echo 1; @endphp',
                '<?php  echo 1;  ?>',
            ],
            'php inline' => [
                '@php($x = 1)',
                '<?php ($x = 1); ?>',
            ],
            'unset' => [
                '@unset($a)',
                '<?php unset($a); ?>',
            ],
            'html attribute helpers' => [
                '@checked($a) @disabled($a) @required($a) @readonly($a) @selected($a) @bool($a)',
                "<?php echo ((\$a) ? 'checked' : ''); ?> <?php echo ((\$a) ? 'disabled' : ''); ?> "
                . "<?php echo ((\$a) ? 'required' : ''); ?> <?php echo ((\$a) ? 'readonly' : ''); ?> "
                . "<?php echo ((\$a) ? 'selected' : ''); ?> <?php echo ((\$a) ? 'true' : 'false'); ?>",
            ],
            'push and stack' => [
                "@push('s')x @endpush @stack('s')",
                "<?php \$__edge->startPush('s'); ?>x <?php \$__edge->stopPush(); ?> "
                . "<?php echo \$__edge->yieldPushContent('s'); ?>",
            ],
            'pushIf / elsePushIf / elsePush' => [
                "@pushIf(\$a, 's')x @elsePushIf(\$b, 't')y @elsePush('u')z @endPushIf",
                "<?php if(\$a): \$__edge->startPush( 's'); ?>x "
                . "<?php \$__edge->stopPush(); elseif(\$b): \$__edge->startPush( 't'); ?>y "
                . "<?php \$__edge->stopPush(); else: \$__edge->startPush('u'); ?>z "
                . '<?php $__edge->stopPush(); endif; ?>',
            ],
            'pushOnce with id' => [
                "@pushOnce('s', 'id')x @endPushOnce",
                "<?php if (!isset(\$__edge->renderOnce['id'])): \$__edge->renderOnce['id'] = true; "
                . "\$__edge->startPush('s'); ?>x <?php \$__edge->stopPush(); endif; ?>",
            ],
            'include' => [
                "@include('a', ['b' => 1])",
                "<?php echo \$__edge->render('a', ['b' => 1], $edgeArgs); ?>",
            ],
            'includeIf' => [
                "@includeIf('a')",
                "<?php if (\$__edge->exists('a')) echo \$__edge->render('a', $edgeArgs); ?>",
            ],
            'each' => [
                "@each('v', \$items, 'i')",
                "<?php echo \$__edge->renderEach('v', \$items, 'i'); ?>",
            ],
            'extends' => [
                "@extends('layout')",
                "\n<?php echo \$__edge->render('layout', $edgeArgs); ?>",
            ],
            'section with end' => [
                "@section('s')x @endsection",
                "<?php \$__edge->startSection('s'); if (\$__edge->hasParent('s')): ?>x "
                . '<?php endif; $__edge->stopSection(); ?>',
            ],
            'section inline' => [
                "@section('s', 'inline')",
                "<?php \$__edge->startSection('s', 'inline'); ?>",
            ],
            'section show' => [
                "@section('s')x @show",
                "<?php \$__edge->startSection('s'); if (\$__edge->hasParent('s')): ?>x "
                . '<?php endif; echo $__edge->yieldSection(); ?>',
            ],
            'section append' => [
                "@section('s')x @append",
                "<?php \$__edge->startSection('s'); if (\$__edge->hasParent('s')): ?>x "
                . '<?php endif; $__edge->appendSection(); ?>',
            ],
            'section stop' => [
                "@section('s')x @stop",
                "<?php \$__edge->startSection('s'); if (\$__edge->hasParent('s')): ?>x "
                . '<?php endif; $__edge->stopSection(); ?>',
            ],
            'section overwrite' => [
                "@section('s')x @overwrite",
                "<?php \$__edge->startSection('s'); if (\$__edge->hasParent('s')): ?>x "
                . '<?php endif; $__edge->stopSection(true); ?>',
            ],
            'yield' => [
                "@yield('s') @yield('s', 'd')",
                "<?php echo \$__edge->yieldContent('s'); ?> <?php echo \$__edge->yieldContent('s', 'd'); ?>",
            ],
            'hasSection' => [
                "@hasSection('s')",
                "<?php if (! empty(trim(\$__edge->yieldContent('s')))): ?>",
            ],
            'json' => [
                '@json($a) @json($a, 0)',
                '<?php echo e(json_encode($a, 15, 512)); ?> <?php echo e(json_encode($a, 0, 512)); ?>',
            ],
            'js' => [
                '@js($a)',
                '<?php echo \Windwalker\Edge\EdgeHelper::toJS($a, true); ?>',
            ],
            'class' => [
                "@class(['a', 'b' => \$c])",
                "class=\"<?php echo \\Windwalker\\Edge\\EdgeHelper::toCssClasses(['a', 'b' => \$c]) ?>\"",
            ],
            'escaped echo' => [
                '{{ $a }}',
                '<?php echo $__edge->escape($a); ?>',
            ],
            'raw echo' => [
                '{!! $a !!}',
                '<?php echo $a; ?>',
            ],
            'echo with default' => [
                "{{ \$a or 'd' }}",
                "<?php echo \$__edge->escape(isset(\$a) ? \$a : 'd'); ?>",
            ],
            'escaped echo tag is output literally' => [
                '@{{ $a }}',
                '{{ $a }}',
            ],
            'comment' => [
                '{{-- c --}}',
                '<?php /* c */ ?>',
            ],
            'verbatim' => [
                '@verbatim {{ $a }} @endverbatim',
                ' {{ $a }} ',
            ],
            'unknown directive is left untouched' => [
                '@unknown($a)',
                '@unknown($a)',
            ],
            'slot' => [
                "@slot('n')x @endslot",
                "<?php \$__data = get_defined_vars(); \$__edge->slot('n')"
                . '(function (...$__scope) use ($__edge, $__data) { extract($__data); ?>x '
                . '<?php }); $__edge->endSlot(); ?>',
            ],
        ];
    }

    #[Test]
    public function compileOnceGeneratesUniqueIdWhenOmitted(): void
    {
        $result = $this->instance->compile('@once x @endonce');

        self::assertMatchesRegularExpression(
            '/^<\?php if \(!isset\(\$__edge->renderOnce\[\'(\w+)\'\]\)\): '
            . '\$__edge->renderOnce\[\'\1\'\] = true; \?> x <\?php endif; \?>$/',
            $result
        );
    }

    #[Test]
    public function compileForelseNumbersNestedLoops(): void
    {
        $result = $this->instance->compile(
            '@forelse($a as $b) @forelse($b as $c) @empty @endforelse @empty @endforelse'
        );

        self::assertStringContainsString('$__empty_1 = true; foreach($a as $b)', $result);
        self::assertStringContainsString('$__empty_2 = true; foreach($b as $c)', $result);
        self::assertSame(
            2,
            substr_count($result, 'if ($__empty_')
        );
        self::assertLessThan(
            strpos($result, 'if ($__empty_1)'),
            strpos($result, 'if ($__empty_2)')
        );
    }

    #[Test]
    public function compileCustomDirective(): void
    {
        $this->instance->directive('upper', fn(string $expr) => "<?php echo strtoupper{$expr}; ?>");

        self::assertSame("<?php echo strtoupper('a'); ?>", $this->instance->compile("@upper('a')"));
        self::assertArrayHasKey('upper', $this->instance->getDirectives());
    }

    #[Test]
    public function compileWithCustomParser(): void
    {
        $this->instance->parser(fn(string $value) => str_replace('[[name]]', 'Edge', $value));

        self::assertSame('Hello Edge', $this->instance->compile('Hello [[name]]'));
        self::assertCount(1, $this->instance->getParsers());
    }

    #[Test]
    public function setContentTagsChangesEchoSyntax(): void
    {
        $this->instance->setContentTags('[[', ']]');
        $this->instance->setEscapedContentTags('[[[', ']]]');
        $this->instance->setRawTags('<<', '>>');

        self::assertSame('<?php echo $a; ?>', $this->instance->compile('<< $a >>'));
        self::assertSame('<?php echo $__edge->escape($a); ?>', $this->instance->compile('[[ $a ]]'));
        self::assertSame('<?php echo e($a); ?>', $this->instance->compile('[[[ $a ]]]'));
    }

    #[Test]
    public function contentTagGettersReturnUnescapedTags(): void
    {
        $compiler = new EdgeCompiler();
        $compiler->setContentTags('[[', ']]');
        $compiler->setEscapedContentTags('[[[', ']]]');

        self::assertSame(['[[', ']]'], $compiler->getContentTags());
        self::assertSame(['[[[', ']]]'], $compiler->getEscapedContentTags());
    }
}
